import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../CONTROLLERS/pantry_controller.dart';
import 'add_ingredient_view.dart';

class PantryHomeView extends ConsumerWidget {
  const PantryHomeView({super.key});

    @override
      Widget build(BuildContext context, WidgetRef ref) {
          final pantryList = ref.watch(pantryProvider);

              return Scaffold(
                    appBar: AppBar(
                            title: const Text('Smart Pantry Inventory'),
                                    actions: [
                                              IconButton(
                                                          icon: const Icon(Icons.refresh),
                                                                      onPressed: () => ref.read(pantryProvider.notifier).loadInventory(),
                                                                                ),
                                                                                        ],
                                                                                              ),
                                                                                                    body: pantryList.isEmpty
                                                                                                              ? const Center(child: Text('No items in pantry yet. Tap + to add!'))
                                                                                                                        : ListView.builder(
                                                                                                                                      itemCount: pantryList.length,
                                                                                                                                                    itemBuilder: (context, index) {
                                                                                                                                                                    final item = pantryList[index];
                                                                                                                                                                                    return ListTile(
                                                                                                                                                                                                      title: Text(item.name),
                                                                                                                                                                                                                        subtitle: Text('Qty: ${item.quantity} ${item.unit} | Expires: ${item.expiryDate}'),
                                                                                                                                                                                                                                          trailing: IconButton(
                                                                                                                                                                                                                                                              icon: const Icon(Icons.delete, color: Colors.redAccent),
                                                                                                                                                                                                                                                                                  onPressed: () {
                                                                                                                                                                                                                                                                                                        if (item.id != null) {
                                                                                                                                                                                                                                                                                                                                ref.read(pantryProvider.notifier).removeIngredient(item.id!);
                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                            ),
                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                          },
                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                            floatingActionButton: FloatingActionButton(
                                                                                                                                                                                                                                                                                                                                                                                                                                                    onPressed: () {
                                                                                                                                                                                                                                                                                                                                                                                                                                                              Navigator.push(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          context,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      MaterialPageRoute(builder: (context) => const AddIngredientView()),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                child: const Icon(Icons.add),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            